"""
ScholaCore CLEAN-SLATE REBUILD -- Phase 1.

This DELETES every tracked file currently in the repo (the old v1
Vite/React five-role app AND the interim v2 static-HTML draft) and
replaces it with a fresh scaffold:

  - Vite + TypeScript + Tailwind (vanilla, no framework), matching the
    original brief literally.
  - firebase/firestore.rules + firebase/storage.rules -- single source
    of truth this time, three roles only: student / teacher / admin.
  - firebase.json wired to those rule paths (was missing entirely
    before -- `firebase deploy --only firestore:rules` had nothing
    telling it which file to use).
  - .env.example with correct VITE_ prefixes on every client-side key
    from the start.
  - api/_lib/firebaseAdmin.ts, a clean Admin SDK singleton.
  - README.md documenting the actual stack (no stale Gemini references,
    no dead role names).

This is destructive to the repo's tracked files. It does NOT touch git
history -- you can still find every old file in past commits -- but
`git status` after running this will show the entire old tree deleted
and the new scaffold added, all in one commit.

Run on your Windows machine with the repo already cloned.

Usage:
    python rebuild_scholacore_clean.py [path_to_repo]
"""
import base64, os, subprocess, sys

DEFAULT_REPO = r"C:\Users\Bosslady\SCHOLACORE\scholacore"

FILES = {
    '.env.example': '',
    '.gitignore': 'bm9kZV9tb2R1bGVzLwpkaXN0LwouZW52Ci5lbnYubG9jYWwKLnZlcmNlbC8KKi5sb2cK',
    'README.md': '',
    'api/_lib/firebaseAdmin.ts': '',
    'firebase.json': 'ewogICJmaXJlc3RvcmUiOiB7CiAgICAicnVsZXMiOiAiZmlyZWJhc2UvZmlyZXN0b3JlLnJ1bGVzIgogIH0sCiAgInN0b3JhZ2UiOiB7CiAgICAicnVsZXMiOiAiZmlyZWJhc2Uvc3RvcmFnZS5ydWxlcyIKICB9Cn0K',
    'firebase/firestore.rules': '',
    'firebase/schema.md': '',
    'firebase/storage.rules': '',
    'index.html': '',
    'package.json': '',
    'postcss.config.js': 'ZXhwb3J0IGRlZmF1bHQgewogIHBsdWdpbnM6IHsKICAgIHRhaWx3aW5kY3NzOiB7fSwKICAgIGF1dG9wcmVmaXhlcjoge30KICB9Cn07Cg==',
    'src/firebase.ts': '',
    'src/main.ts': '',
    'src/style.css': '',
    'src/telegram.ts': '',
    'tailwind.config.js': '',
    'tsconfig.json': '',
    'vite.config.ts': '',
}


def run(cmd, cwd):
    print(">", " ".join(cmd))
    result = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
    if result.stdout.strip():
        print(result.stdout)
    if result.returncode != 0 and result.stderr.strip():
        print(result.stderr)
    return result.returncode == 0


def main():
    repo_root = sys.argv[1] if len(sys.argv) > 1 else DEFAULT_REPO
    if not os.path.isdir(repo_root):
        print(f"Repo path not found: {repo_root}")
        sys.exit(1)

    git_dir = os.path.join(repo_root, ".git")
    if not os.path.isdir(git_dir):
        print(f"{repo_root} is not a git repository (no .git folder). Aborting.")
        sys.exit(1)

    # 1. Remove every currently tracked file (old v1 app + v2 draft).
    result = subprocess.run(
        ["git", "ls-files"], cwd=repo_root, capture_output=True, text=True
    )
    tracked = [f for f in result.stdout.splitlines() if f.strip()]
    if tracked:
        if not run(["git", "rm", "-rf", "--cached", "."], repo_root):
            sys.exit(1)
        for rel in tracked:
            full = os.path.join(repo_root, rel.replace("/", os.sep))
            if os.path.isfile(full):
                os.remove(full)
        print(f"removed {len(tracked)} previously tracked files")

    # 2. Write the fresh scaffold.
    for rel_path, b64_content in FILES.items():
        dest = os.path.join(repo_root, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as f:
            f.write(base64.b64decode(b64_content))
        print(f"wrote: {rel_path}")

    print(f"\n{len(FILES)} files written to {repo_root}")

    if not run(["git", "add", "-A"], repo_root):
        sys.exit(1)
    commit_msg = "Clean-slate rebuild: Vite+TS+Tailwind scaffold, single firestore/storage rules source, correct VITE_ env prefixes (Phase 1)"
    if not run(["git", "commit", "-m", commit_msg], repo_root):
        print("Nothing to commit or commit failed -- check output above.")
        sys.exit(1)
    run(["git", "push", "origin", "main"], repo_root)


if __name__ == "__main__":
    main()
